   "sector": "economia",
   "titulo": "Julio Velarde sobre el rol de los bancos centrales: “debemos aprender a no solo buscar la estabilidad de precios, sino buscar evitar crisis”",
   "resumen": "El presidente del BCRP recordó que la crisis de los años 80 hizo retroceder al Perú 36 años y destacó que, como una de las lecciones de ese periodo, el BCRP mantiene desde 1990 el compromiso de no financiar al Gobierno.",
   "fuente": "RPP",
   "url": "https://rpp.pe/economia/economia/julio-velarde-y-su-mensaje-a-los-bancos-centrales-debemos-aprender-a-no-solo-buscar-la-estabilidad-de-precios-sino-buscar-evitar-crisis-noticia-1718409",
   "fecha": "2026-11-18T18:23:21Z",
   "tipo": "comercial",
   "genero": "noticia",
   "imagen": "https://f.rpp-noticias.io/2026/11/18/014301_1930542.jpg?imgdimension=look",
   "geografia": {
    "version": 1,
    "ambito": "peru",
    "zona": "peru",
    "motivo": "contexto_peru_resumen"
   },
   "ambito": "peru",
   "procedencia": "directa",
   "sintesis": "El presidente del BCRP recordó que la crisis de los años 80 hizo retroceder al Perú 36 años y destacó que, como una de las lecciones de ese periodo, el BCRP mantiene desde 1990 el compromiso de no financiar al Gobierno. El presidente del Banco Central de Reserva del Perú ( BCRP ), Julio Velarde , sostuvo que la labor de las autoridades monetarias no debe limitarse a mantener la inflación bajo control, sino que también debe anticiparse a los riesgos que pueden desencadenar crisis económicas y financieras.",
   "puntos": [
    "El presidente del BCRP recordó que la crisis de los años 80 hizo retroceder al Perú 36 años y destacó que, como una de las lecciones de ese periodo, el BCRP mantiene desde 1990 el compromiso de no financiar al Gobierno.",
    "El presidente del Banco Central de Reserva del Perú ( BCRP ), Julio Velarde , sostuvo que la labor de las autoridades monetarias no debe limitarse a mantener la inflación bajo control, sino que también debe anticiparse a los riesgos que pueden desencadenar crisis económicas y financieras.",
    "“Algo que debemos aprender [los bancos centrales] es que el rol no solo es la estabilidad de precios sino buscar evitar crisis\", enfatizó Velarde durante durante una ceremonia en la que la Universidad Científica del Sur le otorgó el título de doctor honoris causa, el primero que concede esta casa de estudios."
   ],
   "datos": [
    {
     "v": "36 años",
     "t": "cantidad",
     "c": "…que la crisis de los años 80 hizo retroceder al Perú 36 años y destacó que, como una de las lecciones de ese periodo…"
    },
    {
     "v": "20 años",
     "t": "cantidad",
     "c": "…y gremios a nivel nacional, por su trayectoria por más de 20 años al mando del BCRP."
    }
   ]
