   "sintesis": "Un fabricante alemán de drones que suministra equipos a Ucrania denuncia un ciberataque contra su infraestructura digital. El grupo alemán de defensa Quantum Systems sufrió el mes pasado un ciberataque que llevó al ejército alemán a dejar temporalmente en tierra su flota de drones , un incidente en el que, según indicaron varias fuentes el viernes, podría estar detrás Rusia .",
